const cds = require('@sap/cds')
const { db } = cds.env.requires
const { sm_url, baseurl, url, identity } = db.credentials || {}
const LOG = cds.log('mtx')

if (sm_url) {
  module.exports = require('./srv-mgr')
} else if (baseurl) {
  if (cds.env.requires['cds.xt.SaasProvisioningService']?.upgrade?.ignoreNonExistingContainers) {
    LOG.warn('SaaS Provisioning Service is configured with ignoreNonExistingContainers. This can cause problems when using HANA TMS v2 as container manager.')
  }
  module.exports = require('./tms')
} else if (db.serverless || db.kind === 'hana-serverless' || (url && identity)) {
  module.exports = require('./serverless')
} else {
  LOG.warn('Neither Service Manager, HANA TMS, nor serverless credentials found. No HANA HDI Containers will be accessible.')
  module.exports = { defaultInstance: ()=> {} }
}
